      let prevLeft = rect.left;
      let prevTop = rect.top;
      let newWidth;
      let newHeight;
      const barHeight = 20;
      let newSize = null;

      const mouseup = () => {
        isResizing = false;
        window.removeEventListener('mousemove', mousemove);
        window.removeEventListener('mouseup', mouseup);
        if (this.callback && newSize) {
          this.callback(newSize);
        }
      };

      const mousemove = (e) => {
        const newX = prevX - e.clientX;
        const newY = prevY - e.clientY;

        if (currentResizer === this.sizers[0]) {
          newWidth = rect.width - newX;
          newHeight = (rect.height - barHeight) + newY;
          const ratio = newHeight / newWidth;
          var ar = this.aspectRatio || ratio;

          if (ratio > ar && newWidth > minWidth) {
            this.outer.style.top = prevTop - newY + 'px';
            this.outer.style.height = newHeight + 'px';
            this.outer.style.width = (newHeight / this.aspectRatio) + 'px';
            newSize = [(newHeight / ar), newHeight];
          } else {
            const actualNewHeight = (newWidth * ar);
            this.outer.style.width = newWidth + 'px';
            this.outer.style.height = actualNewHeight + 'px';
            this.outer.style.top = (prevTop + rect.height - actualNewHeight) + 'px';
            newSize = [newWidth, actualNewHeight];
